"import os
import glob
import json

brain_dir = r"C:\Users\lg\.gemini\antigravity\brain"

# Find all directories in brain_dir
dirs = [os.path.join(brain_dir, d) for d in os.listdir(brain_dir) if os.path.isdir(os.path.join(brain_dir, d))]
# Sort by modification time of the directory or its transcript.jsonl
def get_mtime(d):
    t_path = os.path.join(d, ".system_generated", "logs", "transcript.jsonl")
    if os.path.exists(t_path):
        return os.path.getmtime(t_path)
    return os.path.getmtime(d)

dirs.sort(key=get_mtime, reverse=True)

print("Recent Conversations:")
for d in dirs[:5]:
    conv_id = os.path.basename(d)
    t_path = os.path.join(d, ".system_generated", "logs", "transcript.jsonl")
    mtime = get_mtime(d)
    import datetime
    dt = datetime.datetime.fromtimestamp(mtime).strftime('%Y-%m-%d %H:%M:%S')
    print(f"\n--- Conv ID: {conv_id} (Modified: {dt}) ---")
    if os.path.exists(t_path):
        # Read the last few user inputs
        user_inputs = []
        try:
            with open(t_path, "r", encoding="utf-8") as f:
                for line in f:
                    try:
                        data = json.loads(line)
                        if data.get("type") == "USER_INPUT":
                            user_inputs.append(data.get("content", ""))
                    except Exception as e:
                        pass
            print("Last 5 User Inputs:")
            for ui in user_inputs[-5:]:
                print(f"  > {ui.strip()}")
        except Exception as e:
            print(f"Error reading transcript: {e}")
    else:
        print("No transcript.jsonl found.")
