"const fs = require('fs');
const path = require('path');

const brainDir = "C:\\Users\\lg\\.gemini\\antigravity\\brain";

try {
  const dirs = fs.readdirSync(brainDir)
    .map(name => path.join(brainDir, name))
    .filter(filePath => fs.statSync(filePath).isDirectory());

  const getMTime = (dirPath) => {
    const tPath = path.join(dirPath, ".system_generated", "logs", "transcript.jsonl");
    if (fs.existsSync(tPath)) {
      return fs.statSync(tPath).mtimeMs;
    }
    return fs.statSync(dirPath).mtimeMs;
  };

  dirs.sort((a, b) => getMTime(b) - getMTime(a));

  console.log("Recent Conversations:");
  dirs.slice(0, 5).forEach(dirPath => {
    const convId = path.basename(dirPath);
    const tPath = path.join(dirPath, ".system_generated", "logs", "transcript.jsonl");
    const mtime = getMTime(dirPath);
