"// Global Iframe Message Listener to intercept URL Changes inside the Proxy Frame
window.addEventListener('message', (e) => {
  if (e.data && e.data.type === 'IFRAME_URL_CHANGE') {
    const proxiedUrl = e.data.url;
    const realUrl = unwrapProxyUrl(proxiedUrl);

    // Find matching window and update its address bar
    const iframes = document.querySelectorAll('.browser-iframe');
    iframes.forEach(iframe => {
      if (iframe.contentWindow === e.source) {
        const winDiv = iframe.closest('.window');
        if (winDiv) {
          const addressInput = winDiv.querySelector('.browser-address-input');
          if (addressInput && addressInput.value !== realUrl) {
            addressInput.value = realUrl;
          }
        }
      }
    });
  } else if (e.data && e.data.type === 'IFRAME_WHEEL') {
    handleWorkspaceSwipe(e.data.deltaX, e.data.deltaY, () => {});
  }
});"

