"// Touchpad Swipe Gesture variables (Global scope to be accessible by message listener)
let accumulatedDeltaX = 0;
let accumulatedDeltaY = 0;
let lastWheelTime = 0;
let lastWorkspaceSwitchTime = 0;
const SWITCH_COOLDOWN = 600;
const SWIPE_THRESHOLD = 80;

function handleWorkspaceSwipe(deltaX, deltaY, preventDefaultFn) {
  const now = Date.now();

  // Reset accumulator if user stopped swiping for more than 150ms
  if (now - lastWheelTime > 150) {
    accumulatedDeltaX = 0;
    accumulatedDeltaY = 0;
  }
  lastWheelTime = now;

  // Check if we can switch workspace (not in cooldown)
  if (now - lastWorkspaceSwitchTime < SWITCH_COOLDOWN) {
    accumulatedDeltaX = 0;
    accumulatedDeltaY = 0;
    if (Math.abs(deltaX) > Math.abs(deltaY) * 1.5) {
      preventDefaultFn();
    }
    return;
  }

  // Accumulate horizontal and vertical deltas
  accumulatedDeltaX += deltaX;
  accumulatedDeltaY += deltaY;

  // If direction changed, reset that component
  if (Math.sign(deltaX) !== Math.sign(accumulatedDeltaX - deltaX)) {
    accumulatedDeltaX = deltaX;
  }

  // Always prevent default if the swipe is horizontal-dominant to prevent browser back/forward history navigation
  if (Math.abs(accumulatedDeltaX) > Math.abs(accumulatedDeltaY) * 1.5) {
    preventDefaultFn();
  }

  // Trigger switch if horizontal delta exceeds threshold and is dominant
  if (Math.abs(accumulatedDeltaX) > SWIPE_THRESHOLD && Math.abs(accumulatedDeltaX) > Math.abs(accumulatedDeltaY) * 1.5) {
    if (accumulatedDeltaX > 0) {
      switchWorkspace(state.activeWorkspaceIndex + 1);
    } else {
      switchWorkspace(state.activeWorkspaceIndex - 1);
    }

    // Reset accumulators and set cooldown
    accumulatedDeltaX = 0;
    accumulatedDeltaY = 0;
    lastWorkspaceSwitchTime = now;
  }
}

// Document Elements"

