      try {
        const preventOverscroll = () => {
          if (!document.getElementById('prevent-overscroll-css')) {
            const style = document.createElement('style');
            style.id = 'prevent-overscroll-css';
            style.textContent = 'html, body { overscroll-behavior-x: none !important; overscroll-behavior: none !important; }';
            if (document.head) {
              document.head.appendChild(style);
            } else {
              document.documentElement.appendChild(style);
            }
          }
        };
        preventOverscroll();
        document.addEventListener('DOMContentLoaded', preventOverscroll);
      } catch(e) {}

      // Forward wheel events to parent to allow trackpad workspace switching
      try {
